from z3 import *

n = 17

# Create boolean variables for each edge
x = {}
for i in range(n):
    for j in range(i+1, n):
        x[(i,j)] = Bool(f"x_{i}_{j}")

solver = Optimize()

# Fixed edges
fixed_edges = [(0,15), (3,15), (6,15), (9,15), (11,15), (14,16)]
for (i,j) in fixed_edges:
    if i > j:
        i, j = j, i
    solver.add(x[(i,j)] == True)

# Triangle-free: for each triple, at most 2 edges
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(x[(i,j)], x[(i,k)], x[(j,k)])))

# Maximality: for each non-edge pair, there must be a common neighbor
for i in range(n):
    for j in range(i+1, n):
        if (i,j) in fixed_edges:
            continue  # Already fixed to True
        # If x[(i,j)] is False, then exists k such that x[(i,k)] and x[(j,k)] are True
        # This is: x[(i,j)] OR (exists k: x[(i,k)] AND x[(j,k)])
        common_neighbor = Or([And(x.get((min(i,k), max(i,k)), False), 
                                   x.get((min(j,k), max(j,k)), False)) 
                              for k in range(n) if k != i and k != j])
        solver.add(Or(x[(i,j)], common_neighbor))

# Maximize the number of edges
edge_count = Sum([If(x[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)])
solver.maximize(edge_count)

print("Solving...")
if solver.check() == sat:
    m = solver.model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if m.evaluate(x[(i,j)], model_completion=True):
                edges.append((i,j))
    print(f"Number of edges: {len(edges)}")
    print(f"Edges: {edges}")

    # Verify triangle-free
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if ((i,j) in edges or (j,i) in edges) and \
                   ((i,k) in edges or (k,i) in edges) and \
                   ((j,k) in edges or (k,j) in edges):
                    print(f"TRIANGLE FOUND: ({i},{j},{k})")

    # Verify maximality
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) not in edges:
                has_common = False
                for k in range(n):
                    if k != i and k != j:
                        if ((min(i,k), max(i,k)) in edges and 
                            (min(j,k), max(j,k)) in edges):
                            has_common = True
                            break
                if not has_common:
                    print(f"NOT MAXIMAL: ({i},{j}) has no common neighbor")

    print("Verification complete")
else:
    print("UNSATISFIABLE")

from pysat.solvers import Glucose3
import itertools

n = 17

# Map edge (i,j) to variable index
edge_vars = {}
var_count = 0
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = var_count
        var_count += 1

print(f"Number of edge variables: {var_count}")

# Fixed edges
fixed_edges = [(0,15), (3,15), (6,15), (9,15), (11,15), (14,16)]

# First, let's try to find a maximal triangle-free graph
# We'll use an iterative approach:
# 1. Start with triangle-free constraints
# 2. Find a solution
# 3. Check if it's maximal
# 4. If not, add constraints and repeat

def solve_triangle_free(fixed_present, fixed_absent=None):
    """Find a triangle-free graph with given fixed edges."""
    solver = Glucose3()

    # Fixed present edges
    for (i,j) in fixed_present:
        if i > j:
            i, j = j, i
        solver.add_clause([edge_vars[(i,j)] + 1])

    # Fixed absent edges
    if fixed_absent:
        for (i,j) in fixed_absent:
            if i > j:
                i, j = j, i
            solver.add_clause([-(edge_vars[(i,j)] + 1)])

    # Triangle-free constraints
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                v1 = edge_vars[(i,j)] + 1
                v2 = edge_vars[(i,k)] + 1
                v3 = edge_vars[(j,k)] + 1
                solver.add_clause([-v1, -v2, -v3])

    if solver.solve():
        model = solver.get_model()
        edges = set()
        for (i,j), v in edge_vars.items():
            if model[v] > 0:
                edges.add((i,j))
        return edges
    return None

def check_maximal(edges):
    """Check if graph is maximal triangle-free. Return list of non-maximal pairs."""
    non_maximal = []
    edge_set = set(edges)
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) not in edge_set:
                # Check if adding (i,j) creates a triangle
                creates_triangle = False
                for k in range(n):
                    if k != i and k != j:
                        if (min(i,k), max(i,k)) in edge_set and (min(j,k), max(j,k)) in edge_set:
                            creates_triangle = True
                            break
                if not creates_triangle:
                    non_maximal.append((i,j))
    return non_maximal

# Start with fixed edges
edges = solve_triangle_free(fixed_edges)
if edges is None:
    print("UNSATISFIABLE - no triangle-free graph exists with fixed edges")
else:
    print(f"Initial solution has {len(edges)} edges")

    # Iteratively enforce maximality
    iteration = 0
    while iteration < 100:
        non_maximal = check_maximal(edges)
        if not non_maximal:
            print(f"Found maximal triangle-free graph with {len(edges)} edges after {iteration} iterations")
            break

        # For each non-maximal pair, we need to either add the edge or ensure a common neighbor exists
        # Let's try adding edges greedily
        added = False
        for (i,j) in non_maximal:
            # Try adding this edge
            test_edges = edges | {(i,j)}
            # Check if still triangle-free
            is_triangle_free = True
            for k in range(n):
                if k != i and k != j:
                    if (min(i,k), max(i,k)) in test_edges and (min(j,k), max(j,k)) in test_edges:
                        is_triangle_free = False
                        break
            if is_triangle_free:
                edges.add((i,j))
                added = True

        if not added:
            # Need to use SAT solver with additional constraints
            # For each non-maximal pair, force at least one common neighbor
            print(f"Greedy failed, using SAT solver...")
            break

        iteration += 1

    print(f"Final edges: {sorted(edges)}")
